import{_ as r,I as o,g as a,j as e}from"./chunks/framework.CjoWWfVe.js";const c=JSON.parse('{"title":"Быстрый старт","description":"Первые шаги в ОмниКрафт ЕРП. Базовая настройка, перенос остатков и принципы безопасности данных.","frontmatter":{"title":"Быстрый старт","description":"Первые шаги в ОмниКрафт ЕРП. Базовая настройка, перенос остатков и принципы безопасности данных.","order":3},"headers":[],"relativePath":"ru/docs/getting-started.md","filePath":"ru/docs/getting-started.md"}'),n={name:"ru/docs/getting-started.md"};function s(l,t,i,g,d,p){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="быстрыи-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#быстрыи-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h1><p>Эта страница поможет вам правильно настроить ОмниКрафт ЕРП при первом запуске и безболезненно перенести данные в программу из вашего предыдущего учёта (блокнотов, Excel-таблиц или других программ).</p><hr><h2 id="🌍-язык-и-безопасность-данных" tabindex="-1">🌍 Язык и безопасность данных <a class="header-anchor" href="#🌍-язык-и-безопасность-данных" aria-label="Permalink to &quot;🌍 Язык и безопасность данных&quot;">​</a></h2><p><strong>Локализация:</strong> Программа поддерживает несколько языков и при первом запуске автоматически определяет язык вашей операционной системы. Вы всегда можете изменить его вручную: в верхнем меню выберите <strong>Файл ➔ Настройки программы</strong>, выберите нужный язык и перезапустите приложение.</p><p><strong>Безопасность:</strong> Ваши данные — это ваша собственность. Мы <strong>не собираем, не храним и не обрабатываем ваши личные и персональные данные и данные вашего бизнеса</strong>. Программа не требует регистрации с указанием имени, электронной почты или номера телефона.</p><div class="info custom-block"><p class="custom-block-title">О сохранности информации и резервных копиях</p><p>Мы прикладываем все усилия, чтобы свести риски к минимуму: в программу встроены современные инструменты защиты данных, база использует режим ВАЛ (защита от сбоев питания) и делает автоматические теневые копии.</p><p>Тем не менее, стопроцентная гарантия сохранности информации невозможна — потеря данных может произойти из-за системных ошибок ОС, вредоносного ПО, физического износа жесткого диска или по другим причинам. Забота о сохранности данных остается вашей зоной ответственности.</p><p>Рекомендуем периодически создавать ручные резервные копии: <strong>Файл ➔ Экспорт данных</strong>. Основная бинарная копия (<code>.db</code>) сохраняет вашу систему целиком. Однако в качестве дополнительного страховочного варианта желательно выгружать данные и во втором формате — «Таблицы текущего пространства (.zip с CSV)». Если бинарный файл базы когда-либо получит микроповреждения из-за дисковых сбоев и не откроется в программе, у вас будет запасной вариант восстановления.</p></div><hr><h2 id="🚚-перенос-данных-из-предыдущего-учета" tabindex="-1">🚚 Перенос данных из предыдущего учёта <a class="header-anchor" href="#🚚-перенос-данных-из-предыдущего-учета" aria-label="Permalink to &quot;🚚 Перенос данных из предыдущего учёта&quot;">​</a></h2><p>Если вы переходите на ОмниКрафт ЕРП из другой системы, вам не нужно вручную вбивать историю всех прошлых продаж за несколько лет. Достаточно перенести текущий «срез» вашего бизнеса за два простых шага.</p><h3 id="шаг-1-внесите-текущее-имущество-и-материалы" tabindex="-1">Шаг 1. Внесите текущее имущество и материалы <a class="header-anchor" href="#шаг-1-внесите-текущее-имущество-и-материалы" aria-label="Permalink to &quot;Шаг 1. Внесите текущее имущество и материалы&quot;">​</a></h3><ol><li>Откройте вкладку <strong>Мастерская</strong> и внесите всё ваше текущее оборудование и инструменты по цене их изначальной покупки.</li><li>Откройте вкладку <strong>Сырьё</strong> и внесите фактические остатки материалов (например, кожу, химию, фурнитуру, если у вас кожевенное производство), которые есть у вас на полках прямо сейчас.</li></ol><p><em>Что произойдет:</em> Программа поставит эти ценности на Баланс мастерской. При этом она автоматически зафиксирует траты на их покупку в журнале ДДС (Движения денежных средств). На этом этапе сальдо ДДС логично уйдет в глубокий минус — система зафиксировала объем ваших исторических инвестиций в бизнес.</p><h3 id="шаг-2-зафиксируите-стартовые-финансы-ддс-и-капитал" tabindex="-1">Шаг 2. Зафиксируйте стартовые финансы (ДДС и Капитал) <a class="header-anchor" href="#шаг-2-зафиксируите-стартовые-финансы-ддс-и-капитал" aria-label="Permalink to &quot;Шаг 2. Зафиксируйте стартовые финансы (ДДС и Капитал)&quot;">​</a></h3><p>В философии ОмниКрафт ЕРП по умолчанию действует модель <strong>смешанных финансов</strong>. Это означает, что отрицательное сальдо кассы в ДДС — абсолютно нормальный показатель: оно наглядно отражает объем ваших исторических инвестиций, вложенных в покупку станков, инструментов и сырья на первом шаге.</p><p>Как только бизнес начнет приносить выручку от продаж готовой продукции, сальдо ДДС будет постепенно расти и выйдет в плюс, показав полную окупаемость ваших стартовых вложений.</p><p><strong>Если вы хотите разделить личные деньги и деньги бизнеса (задать стартовое сальдо):</strong></p><ol><li>Если имущество и инструменты были куплены задолго до этого из личных сбережений и вы не хотите, чтобы они уменьшали кассу бизнеса, просто включите у них опцию <strong>«Без учёта затрат в ДДС»</strong> при внесении на вкладке <strong>Мастерская</strong>. Имущество встанет на баланс в Капитал, а в кассе ДДС не возникнет расхода.</li><li>Если в кассе или на отдельной рабочей карте мастерской уже есть физический остаток денег (например, 50 000 ₽), перейдите во вкладку <strong>ДДС</strong> и в форме <strong>«Внести прочие операции»</strong> создайте операцию: <ul><li><strong>Тип операции:</strong> Внереализационный доход;</li><li><strong>Категория:</strong> Прочее;</li><li><strong>Сумма:</strong> Ваш фактический остаток денег;</li><li><strong>Комментарий:</strong> <em>«Стартовый остаток кассы на момент запуска программы»</em>.</li></ul></li></ol><p>Всё! Ваша база настроена, математика сведена, а Баланс и ДДС показывают реальную картину без лишней рутины.</p><hr><h2 id="🚀-базовые-настроики-ценообразования" tabindex="-1">🚀 Базовые настройки ценообразования <a class="header-anchor" href="#🚀-базовые-настроики-ценообразования" aria-label="Permalink to &quot;🚀 Базовые настройки ценообразования&quot;">​</a></h2><p>Перед тем как перейти к созданию изделий (вкладка Калькулятор), важно задать финансовые правила вашей мастерской. Перейдите во вкладку <strong>Настройки</strong> и установите три главных параметра:</p><h3 id="_1-системная-ставка-мастера-₽-час" tabindex="-1">1. Системная ставка мастера (₽/час) <a class="header-anchor" href="#_1-системная-ставка-мастера-₽-час" aria-label="Permalink to &quot;1. Системная ставка мастера (₽/час)&quot;">​</a></h3><p>Это стоимость одного часа работы мастера.</p><ul><li><strong>Если вы нанимаете помощников:</strong> Укажите здесь их среднюю часовую ставку. Программа будет считать эти деньги прямым расходом и строго включать в себестоимость.</li><li><strong>Если вы работаете на себя (соло-мастер):</strong> Вы можете указать ставку <code>0</code>. В этом случае вам не придется делать лишние проводки по выплате «зарплаты» самому себе. Однако помните: если ваша ставка равна нулю, стоимость вашего труда должна быть заложена в итоговую <em>глобальную наценку</em>.</li></ul><h3 id="_2-глобальная-наценка" tabindex="-1">2. Глобальная наценка (%) <a class="header-anchor" href="#_2-глобальная-наценка" aria-label="Permalink to &quot;2. Глобальная наценка (%)&quot;">​</a></h3><p>Это множитель маржинальности. Программа автоматически применит его к чистой себестоимости изделия (материалы + работа + накладные расходы), чтобы рассчитать для вас <strong>Рекомендуемую розничную цену</strong>.</p><h3 id="_3-накладные-расходы-глобальные-нормативы" tabindex="-1">3. Накладные расходы (Глобальные нормативы) <a class="header-anchor" href="#_3-накладные-расходы-глобальные-нормативы" aria-label="Permalink to &quot;3. Накладные расходы (Глобальные нормативы)&quot;">​</a></h3><p>Накладные расходы — это невидимые затраты, которые несет ваша мастерская: электричество, аренда, расходники. В настройках вы задаете их базовый уровень. Они могут быть двух типов:</p><ul><li><strong>Процентные (%):</strong> Считаются как процент от базовой себестоимости изделия.</li><li><strong>Фиксированные (₽):</strong> Твердая сумма, которая прибавляется к каждому произведенному изделию.</li></ul><p><strong>Индивидуальная настройка в рецептах:</strong> Вам не придется менять глобальные настройки каждый раз, если разные изделия требуют разных затрат. При создании рецепта конкретного изделия в Калькуляторе программа предложит вам умную панель коэффициентов:</p><ul><li>Если на изделие уходит в два раза больше электричества и клея, вы просто ставите в её рецепте коэффициент накладных <code>2.0</code> (программа умножит глобальный норматив на два).</li><li>Если для простого брелока сложное оборудование не используется вовсе, вы ставите коэффициент <code>0</code>, и эти расходы не войдут в его себестоимость.</li></ul><p>После заполнения этих параметров ваша система полностью готова к работе. Вы можете переходить во вкладку <strong>Калькулятор</strong> и создавать свои первые технологические карты изделий.</p>',33)])])}const u=r(n,[["render",s]]);export{c as __pageData,u as default};
